        headers["content-type"] = "application/json"
        body = " { " + \
            " \"username\" : \"superadmin\", " + \
            " \"password\" : \"pass1\" " + \
            " } "
        res_superadmin = requests \
                .post(self.baseUrlOfSut + "/users/v1/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_superadmin =  res_superadmin.json()["auth_token"]
        
        auth_superadmin = "Bearer " + token_superadmin
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"username\" : \"name1\", " + \
            " \"password\" : \"pass1\" " + \
            " } "
        res_name1 = requests \
                .post(self.baseUrlOfSut + "/users/v1/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_name1 =  res_name1.json()["auth_token"]
        
        auth_name1 = "Bearer " + token_name1
        
        headers = {}
        headers["Authorization"] = auth_superadmin # superadmin
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"password\" : \"pass4\" " + \
            " } "
        headers['Accept'] = "application/json"
        res_0 = requests \
                .put(self.baseUrlOfSut + "/users/v1/name1/password",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 400
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["status"] == "fail"
        assert res_0.json()["message"] == "User Not Found"
        
        # Fault109. HTTP Violation: no-401-if-no-authenticate.
        # Fault200. Schema Violation: Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.contentType.notAllowed Response Content-Type header 'application/problem+json' does not match any allowed types. Must be one of: [application/json].
        headers = {}
        headers["Authorization"] = auth_name1 # name1
        headers["content-type"] = "application/json"
        body = {}
        body = " { " + \
            " \"password\" : \"pass4\" " + \
            " } "
        headers['Accept'] = "*/*"
        res_1 = requests \
                .put(self.baseUrlOfSut + "/users/v1/name1/password",
                    headers=headers, data=body, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 401
        assert "www-authenticate" not in res_1.headers
        assert "application/problem+json" in res_1.headers["content-type"]
        assert res_1.json()["detail"] == "No authorization token provided"
        assert res_1.json()["status"] == 401
        assert res_1.json()["title"] == "Unauthorized"
        assert res_1.json()["type"] == "about:blank"
    
    
